-- seatunnel-console P1 schema. See docs/schema.md for the reasoning behind each table.
-- Conventions: primary keys are UUID v7 strings generated by the console (CHAR(36));
-- times are DATETIME(3) in the server time zone; soft-deleted rows carry deleted_at, and a
-- generated column keeps names unique among live rows only.

CREATE TABLE sys_user
(
    id            CHAR(36)     NOT NULL,
    username      VARCHAR(64)  NOT NULL,
    password_hash VARCHAR(100) NOT NULL COMMENT 'BCrypt',
    display_name  VARCHAR(64)  NULL,
    role          VARCHAR(16)  NOT NULL COMMENT 'ADMIN | USER',
    enabled       TINYINT(1)   NOT NULL DEFAULT 1,
    last_login_at DATETIME(3)  NULL,
    created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY uk_sys_user_username (username)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'console accounts; disabled instead of deleted';

CREATE TABLE project
(
    id          CHAR(36)     NOT NULL,
    name        VARCHAR(64)  NOT NULL,
    description VARCHAR(512) NULL,
    created_by  CHAR(36)     NULL,
    created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    deleted_at  DATETIME(3)  NULL,
    live_name   VARCHAR(64) AS (IF(deleted_at IS NULL, name, NULL)) STORED,
    PRIMARY KEY (id),
    UNIQUE KEY uk_project_live_name (live_name)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'groups jobs and holds project parameters; no permission isolation';

CREATE TABLE project_param
(
    id          CHAR(36)      NOT NULL,
    project_id  CHAR(36)      NOT NULL,
    param_key   VARCHAR(128)  NOT NULL,
    param_value VARCHAR(1024) NOT NULL,
    description VARCHAR(512)  NULL,
    created_by  CHAR(36)      NULL,
    created_at  DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at  DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY uk_project_param_key (project_id, param_key)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'project-level variables (priority: startup > job > project > built-in)';

CREATE TABLE datasource
(
    id            CHAR(36)     NOT NULL,
    name          VARCHAR(64)  NOT NULL,
    type          VARCHAR(32)  NOT NULL COMMENT 'MYSQL | POSTGRESQL | ELASTICSEARCH',
    description   VARCHAR(512) NULL,
    config_json   JSON         NOT NULL COMMENT 'non-secret connection properties: host, port, database, options',
    secret_cipher TEXT         NULL COMMENT 'AES-GCM encrypted JSON of secret properties (password, api key); key from CONSOLE_SECRET_KEY',
    created_by    CHAR(36)     NULL,
    created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    deleted_at    DATETIME(3)  NULL,
    live_name     VARCHAR(64) AS (IF(deleted_at IS NULL, name, NULL)) STORED,
    PRIMARY KEY (id),
    UNIQUE KEY uk_datasource_live_name (live_name)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'global datasources; credentials are only decrypted in memory at submit time';

CREATE TABLE seatunnel_metadata
(
    id                CHAR(36)    NOT NULL,
    seatunnel_version VARCHAR(32) NOT NULL,
    metadata_json     LONGTEXT    NOT NULL COMMENT 'output of bin/seatunnel-metadata-export.sh',
    connector_count   INT         NOT NULL,
    imported_by       CHAR(36)    NULL,
    imported_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY uk_seatunnel_metadata_version (seatunnel_version)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'connector option rules per SeaTunnel version';

CREATE TABLE job_definition
(
    id                 CHAR(36)     NOT NULL,
    project_id         CHAR(36)     NOT NULL,
    name               VARCHAR(128) NOT NULL,
    job_type           VARCHAR(16)  NOT NULL COMMENT 'BATCH | STREAMING',
    edit_mode          VARCHAR(16)  NOT NULL COMMENT 'FORM | SCRIPT; FORM can be converted to SCRIPT, never back',
    current_version_id CHAR(36)     NULL COMMENT 'null until the first save',
    description        VARCHAR(512) NULL,
    created_by         CHAR(36)     NULL,
    created_at         DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at         DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    deleted_at         DATETIME(3)  NULL,
    live_name          VARCHAR(128) AS (IF(deleted_at IS NULL, name, NULL)) STORED,
    PRIMARY KEY (id),
    UNIQUE KEY uk_job_definition_live_name (project_id, live_name)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'job identity; content lives in job_version';

CREATE TABLE job_version
(
    id                CHAR(36)     NOT NULL,
    job_definition_id CHAR(36)     NOT NULL,
    version_no        INT          NOT NULL,
    form_json         JSON         NULL COMMENT 'wizard state; null for script-mode versions',
    hocon_template    MEDIUMTEXT   NOT NULL COMMENT 'references datasource ids and variables only, never credentials',
    params_json       JSON         NULL COMMENT 'job-level variables',
    seatunnel_version VARCHAR(32)  NULL COMMENT 'metadata version the form was built against',
    remark            VARCHAR(512) NULL,
    created_by        CHAR(36)     NULL,
    created_at        DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY uk_job_version_no (job_definition_id, version_no)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'immutable job versions; every save adds a row';

CREATE TABLE job_version_datasource
(
    job_version_id CHAR(36) NOT NULL,
    datasource_id  CHAR(36) NOT NULL,
    PRIMARY KEY (job_version_id, datasource_id),
    KEY idx_job_version_datasource_ds (datasource_id)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'datasources referenced by a version; blocks deleting datasources still in use';

CREATE TABLE job_schedule
(
    job_definition_id      CHAR(36)      NOT NULL,
    cron                   VARCHAR(64)   NOT NULL COMMENT 'XXL-JOB cron, e.g. 0 0 2 * * ?',
    enabled                TINYINT(1)    NOT NULL DEFAULT 0,
    fail_retry_count       INT           NOT NULL DEFAULT 0 COMMENT 'retried by the console handler inside one instance; XXL-JOB retry stays 0',
    retry_interval_seconds INT           NOT NULL DEFAULT 60,
    timeout_seconds        INT           NOT NULL DEFAULT 0 COMMENT 'XXL-JOB executor timeout; 0 = none',
    block_strategy         VARCHAR(32)   NOT NULL DEFAULT 'SERIAL_EXECUTION',
    misfire_strategy       VARCHAR(32)   NOT NULL DEFAULT 'DO_NOTHING',
    xxl_job_id             INT           NULL,
    sync_status            VARCHAR(16)   NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING | SYNCED | FAILED',
    sync_error             VARCHAR(1024) NULL,
    synced_at              DATETIME(3)   NULL,
    created_by             CHAR(36)      NULL,
    created_at             DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at             DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (job_definition_id),
    UNIQUE KEY uk_job_schedule_xxl_job (xxl_job_id)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'batch job schedule; the console is the source of truth, XXL-JOB mirrors it';

CREATE TABLE backfill_batch
(
    id                 CHAR(36)    NOT NULL,
    job_definition_id  CHAR(36)    NOT NULL,
    start_time         DATETIME(3) NOT NULL COMMENT 'first scheduled time, inclusive',
    end_time           DATETIME(3) NOT NULL COMMENT 'last scheduled time, inclusive',
    parallelism        INT         NOT NULL DEFAULT 1,
    use_latest_version TINYINT(1)  NOT NULL DEFAULT 1,
    total_runs         INT         NOT NULL,
    status             VARCHAR(16) NOT NULL COMMENT 'RUNNING | FINISHED | CANCELED',
    created_by         CHAR(36)    NULL,
    created_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    finished_at        DATETIME(3) NULL,
    PRIMARY KEY (id),
    KEY idx_backfill_batch_job (job_definition_id, created_at)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'one backfill request; its runs are job_instance rows with backfill_batch_id';

CREATE TABLE job_instance
(
    id                   CHAR(36)      NOT NULL,
    project_id           CHAR(36)      NOT NULL,
    job_definition_id    CHAR(36)      NOT NULL,
    job_version_id       CHAR(36)      NOT NULL,
    trigger_type         VARCHAR(16)   NOT NULL COMMENT 'SCHEDULE | MANUAL | RERUN | BACKFILL',
    scheduled_time       DATETIME(3)   NOT NULL COMMENT 'base time for variables',
    status               VARCHAR(16)   NOT NULL COMMENT 'PENDING | RUNNING | SUCCESS | FAILED | CANCELED',
    attempt_count        INT           NOT NULL DEFAULT 0,
    max_attempts         INT           NOT NULL DEFAULT 1,
    rerun_of_instance_id CHAR(36)      NULL,
    backfill_batch_id    CHAR(36)      NULL,
    engine_type          VARCHAR(16)   NOT NULL DEFAULT 'ZETA',
    xxl_job_id           INT           NULL,
    xxl_log_id           BIGINT        NULL COMMENT 'link to the XXL-JOB scheduler log, for admins',
    variables_json       JSON          NULL COMMENT 'final variable values used by this run',
    config_masked        MEDIUMTEXT    NULL COMMENT 'rendered config with secrets masked',
    read_rows            BIGINT        NULL,
    write_rows           BIGINT        NULL,
    read_bytes           BIGINT        NULL,
    write_bytes          BIGINT        NULL,
    error_message        TEXT          NULL COMMENT 'summary of the last failure',
    validation_status    VARCHAR(16)   NULL COMMENT 'PASSED | MISMATCH | SKIPPED | ERROR',
    source_count         BIGINT        NULL,
    target_count         BIGINT        NULL,
    validation_message   VARCHAR(1024) NULL,
    started_at           DATETIME(3)   NULL,
    finished_at          DATETIME(3)   NULL,
    created_by           CHAR(36)      NULL COMMENT 'null for scheduled runs',
    created_at           DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at           DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_job_instance_job_time (job_definition_id, scheduled_time),
    KEY idx_job_instance_status (status, created_at),
    KEY idx_job_instance_created (created_at),
    KEY idx_job_instance_backfill (backfill_batch_id)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'one logical run; retries are attempts inside it';

CREATE TABLE job_instance_attempt
(
    id              CHAR(36)     NOT NULL,
    instance_id     CHAR(36)     NOT NULL,
    attempt_no      INT          NOT NULL,
    engine_job_id   VARCHAR(64)  NULL COMMENT 'Zeta returns job ids as strings',
    engine_status   VARCHAR(32)  NULL COMMENT 'raw engine status, e.g. FINISHED, FAILED',
    metrics_json    JSON         NULL COMMENT 'last raw engine metrics',
    error_message   TEXT         NULL,
    log_storage_key VARCHAR(512) NULL COMMENT 'archived SeaTunnel job log, resolved by LogStorage',
    log_size_bytes  BIGINT       NULL,
    log_truncated   TINYINT(1)   NOT NULL DEFAULT 0,
    log_archived_at DATETIME(3)  NULL,
    submitted_at    DATETIME(3)  NULL,
    finished_at     DATETIME(3)  NULL,
    created_at      DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at      DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    UNIQUE KEY uk_job_instance_attempt_no (instance_id, attempt_no),
    KEY idx_job_instance_attempt_engine (engine_job_id)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'one engine submission; each retry gets a new engine job id and its own log';

CREATE TABLE job_instance_event
(
    id          CHAR(36)    NOT NULL,
    instance_id CHAR(36)    NOT NULL,
    attempt_no  INT         NULL,
    event_type  VARCHAR(32) NOT NULL COMMENT 'CREATED | SUBMITTED | STATUS_CHANGED | RETRY | VALIDATED | LOG_ARCHIVED | ERROR',
    level       VARCHAR(8)  NOT NULL DEFAULT 'INFO' COMMENT 'INFO | WARN | ERROR',
    message     TEXT        NOT NULL,
    created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (id),
    KEY idx_job_instance_event_instance (instance_id, created_at)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci COMMENT = 'run timeline shown on the instance page';
